#include <iostream>
#include <cassert>

static_assert(sizeof(int) >= 4, "int size must be at least 4 bytes");

int computePositiveSum(int a, int b) {
    assert(a > 0 && b > 0);
    return a + b;
}

int main() {
    int x = 10;
    int y = 20;
    int sum = computePositiveSum(x, y);

    // Using #line directive to ensure deterministic __LINE__ output
    #line 100
    std::cout << "Sum: " << sum << "\n";
    std::cout << "Check passed at line: " << __LINE__ << "\n";
    return 0;
}

#include <iostream>

#define UNSAFE_CUBE(x) ((x) * (x) * (x))

constexpr double safeCube(double x) noexcept {
    return x * x * x;
}

int main() {
    int a = 2;
    double resultSafe = safeCube(++a);
    std::cout << "safeCube(++a): result = " << resultSafe << ", a = " << a << "\n";

    int b = 2;
    double resultMacro = UNSAFE_CUBE(b);
    std::cout << "UNSAFE_CUBE(b): result = " << resultMacro << ", b = " << b << "\n";

    return 0;
}
